package com.tekwatt.admin.dto;import com.tekwatt.admin.entity.*;import java.time.Instant;import java.util.UUID;public record AdminActionResponse(UUID id,UUID actorId,AdminActionType actionType,String targetId,String reason,AdminActionStatus status,Integer responseStatus,String responsePayload,String errorMessage,Instant createdAt,Instant completedAt){public static AdminActionResponse from(AdminAction a){return new AdminActionResponse(a.getId(),a.getActorId(),a.getActionType(),a.getTargetId(),a.getReason(),a.getStatus(),a.getResponseStatus(),a.getResponsePayload(),a.getErrorMessage(),a.getCreatedAt(),a.getCompletedAt());}}
